            new Course { Id = 5, Title = "Calculus I", Code = "MATH101", Description = "Limits, continuity, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00 AM - 10:50 AM", InstructorName = "Dr. Robert Taylor", InstructorBio = "Dr. Taylor is an award-winning mathematics educator with a Ph.D. from Princeton. He has authored three calculus textbooks and received the university's Distinguished Teaching Award twice.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
            new Course { Id = 6, Title = "Linear Algebra", Code = "MATH202", Description = "Vector spaces, linear transformations, matrices, determinants, and eigenvalues. Applications to computer graphics, data science, and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00 AM - 10:20 AM", InstructorName = "Dr. Emily Park", InstructorBio = "Dr. Park specializes in applied linear algebra and numerical methods. She earned her Ph.D. from Caltech and has collaborated with NASA on computational modeling projects.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new Course { Id = 7, Title = "Probability and Statistics", Code = "MATH301", Description = "Fundamentals of probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00 AM - 11:50 AM", InstructorName = "Dr. Robert Taylor", InstructorBio = "Dr. Taylor is an award-winning mathematics educator with a Ph.D. from Princeton. He has authored three calculus textbooks and received the university's Distinguished Teaching Award twice.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },

