arguments.file_text:
@page "/courses"
@rendermode InteractiveServer

@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<div class="row mb-3">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search by title, code, or instructor..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

<table class="table table-striped">
    <thead>
        <tr>
            <th>Code</th>
            <th>Title</th>
            <th>Department</th>
            <th>Credits</th>
            <th>Schedule</th>
            <th></th>
        </tr>
    </thead>
    <tbody>
        @foreach (var course in CatalogService.GetCourses(searchTerm, selectedDepartmentId == 0 ? null : selectedDepartmentId))
        {
            <tr>
                <td>@course.Code</td>
                <td>@course.Title</td>
                <td>@course.DepartmentName</td>
                <td>@course.Credits</td>
                <td>@course.Schedule</td>
                <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
            </tr>
        }
    </tbody>
</table>

@code {
    private string? searchTerm;
    private int selectedDepartmentId;
}

@page "/courses/{Id:int}"

@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course") - University Course Catalog</PageTitle>

@if (course is null)
{
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item active">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Title</h1>
    <span class="badge bg-secondary mb-3">@course.Code</span>
    <span class="badge bg-info mb-3">@course.DepartmentName</span>

    <div class="row mt-3">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@course.Description</p>

            <h4>Schedule</h4>
            <p>@course.Schedule</p>

            <h4>Credits</h4>
            <p>@course.Credits</p>
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Instructor</h5>
                    <h6>@course.InstructorName</h6>
                    <p class="card-text">@course.InstructorBio</p>
                </div>
            </div>
        </div>
    </div>

    <a href="/courses" class="btn btn-outline-secondary mt-3">Back to Course List</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private UniversityCourseCatalog.Models.Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@rendermode InteractiveServer

@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to submit an enrollment request.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@model.StudentName</strong>. Your enrollment request for <strong>@GetCourseName(model.CourseId)</strong> has been received.</p>
        <button class="btn btn-primary" @onclick="Reset">Submit Another Request</button>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment" class="col-md-6">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="studentName" class="form-label">Student Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" />
            <ValidationMessage For="() => model.StudentName" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
